"""Assess predeclared native holding protocol and actual row-owned impulses."""
import argparse,csv,json,hashlib,xml.etree.ElementTree as ET,os
from pathlib import Path
import numpy as np
BASE=Path(__file__).resolve().parents[1]
def read(p):return list(csv.DictReader(p.open()))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--case',required=True);p.add_argument('--tag',required=True);a=p.parse_args();src=BASE/'results'/a.case;out=BASE/'results'/a.tag;out.mkdir(exist_ok=False);m=json.loads((src/'summary.json').read_text());protocol=json.loads((src/'holding_protocol.json').read_text())
 if m['status']!='RUN_COMPLETED_NOT_QUALIFIED' or sha(src/'holding_protocol.json')!=m['holding_protocol_sha256']:raise ValueError('complete trial and predeclared protocol required')
 rows=read(src/'object.csv');t=np.array([float(r['time_s']) for r in rows]);q=np.array([np.fromstring(r['rigid_q'],sep=' ') for r in rows]);v=np.array([np.fromstring(r['rigid_v'],sep=' ') for r in rows]);total=np.array([np.fromstring(r['object_impulse_Ns_Nms'],sep=' ') for r in rows]);dt=m['dt_s'];index={float(x):i for i,x in enumerate(t)};finger=np.zeros((len(t),3,6));support=np.zeros_like(total);surface=np.zeros_like(total);hardware=np.zeros_like(total);ambiguous=0;contactrows=read(src/'contact_rows.csv');has_source=bool(contactrows and 'surface_mask' in contactrows[0])
 for row in contactrows:
  k=index[float(row['time_s'])];mask=int(row['film_mask']);impulse=np.fromstring(row['object_impulse_Ns_Nms'],sep=' ')
  if mask==0:support[k]+=impulse
  elif mask in (1,2,4):finger[k,mask.bit_length()-1]+=impulse
  else:ambiguous+=1
  if has_source and mask:
   if int(row['surface_mask']):surface[k]+=impulse
   else:hardware[k]+=impulse
 partition_error=float(np.max(np.abs(total-support-finger.sum(axis=1))));reference=int(np.argmin(abs(t-protocol['reference_s'])));window=(t>=protocol['window_s'][0]-1e-12)&(t<=protocol['window_s'][1]+1e-12)
 if not window.any():raise ValueError('required hold window NOT RUN')
 supp=read(src/'support.csv');sq=np.array([np.fromstring(r['q'],sep=' ') for r in supp]);st=np.array([float(r['time_s']) for r in supp]);tree=ET.parse(src/'scene.scn');srest=np.fromstring(tree.find("./Node[@name='floor']/MechanicalObject").get('position'),sep=' ');R=float(tree.find("./Node[@name='object']/Node/SphereCollisionModel").get('radius'));supportR=float(tree.find("./Node[@name='floor']/SphereCollisionModel").get('radius'));gap=np.linalg.norm(q[:,:3]-sq,axis=1)-R-supportR;movement=tree.find("./Node[@name='floor']/LinearMovementProjectiveConstraint");knots=np.fromstring(movement.get('keyTimes'),sep=' ');values=np.fromstring(movement.get('movements'),sep=' ').reshape(-1,3);expected=np.stack([np.interp(st,knots,values[:,j])+srest[j] for j in range(3)],axis=1);expected_begin=np.stack([np.interp(st-dt,knots,values[:,j])+srest[j] for j in range(3)],axis=1)
 if (src/'motion_commands.json').exists():
  commands=json.loads((src/'motion_commands.json').read_text());command=next(x for x in commands['commands'] if x['node']=='floor');declared=np.array(command['keyTimes_s']);wanted=np.array(command['movements_m']);expected=np.stack([np.interp(st,declared,wanted[:,j])+srest[j] for j in range(3)],axis=1)
 slip=float(1000*np.max(q[reference,2]-q[window,2]));speed=float(1000*np.linalg.norm(v[window,:3],axis=1).max());drift=float(1000*np.linalg.norm(q[window,:3]-q[reference,:3],axis=1).max());min_gap=float(gap[window].min()*1000);support_force=np.linalg.norm(support[:,:3]/dt,axis=1);maximum_support=float(support_force[window].max());tests=dict(vertical_slip=slip<=protocol['max_vertical_slip_mm'],speed=speed<=protocol['max_speed_mm_s'],support_clearance=min_gap>=protocol['minimum_support_surface_gap_mm'],support_reaction=maximum_support<=protocol['maximum_support_resultant_N'],row_partition=partition_error<=1e-12 and ambiguous==0,gravity=np.linalg.norm(m['gravity_m_s2'])>0)
 tests={k:bool(value) for k,value in tests.items()};mass=protocol['mass_kg'];dv=np.diff(np.vstack([np.zeros(6),v]),axis=0);momentum=mass*dv[:,:3]-mass*np.array(m['gravity_m_s2'])*dt-total[:,:3];angular=.4*mass*R*R*dv[:,3:]-total[:,3:]
 result=dict(status='PASS_EXPERIMENTAL_HOLD_ONLY' if all(tests.values()) else 'FAIL',scope='predeclared external-support-free native holding functionality;NOT time/mesh/energy/material/fabrication certification',tests=tests,protocol=protocol,vertical_slip_mm=slip,translation_drift_mm=drift,max_speed_mm_s=speed,minimum_support_gap_mm=min_gap,maximum_support_reaction_N=maximum_support,hold_mean_finger_object_force_N=(finger[window,:,:3].sum(axis=1)/dt).mean(axis=0).tolist(),row_partition_max_error_Ns_Nms=partition_error,ambiguous_rows=ambiguous,linear_momentum_max_error_Ns=float(np.abs(momentum).max()),sphere_angular_momentum_max_error_Nms=float(np.abs(angular).max()),quaternion_norm_error=float(np.max(abs(np.linalg.norm(q[:,3:],axis=1)-1))),support_end_clock_position_error_m=float(np.max(abs(sq-expected))),support_begin_clock_position_error_m=float(np.max(abs(sq-expected_begin))),support_timing_note='stock LinearMovement uses begin-of-step context;record both clocks,do not silently shift physical state',cable_work=None,contact_area=None,pressure=None,whole_energy='NOT MEASURED',input_hashes={f.name:sha(f) for f in (src/'summary.json',src/'holding_protocol.json',src/'contact_rows.csv',src/'support.csv',src/'object.csv')},source_sha256=sha(Path(__file__)))
 result['hold_mean_surface_object_force_N']=(surface[window,:3]/dt).mean(axis=0).tolist() if has_source else None;result['hold_mean_hardware_only_object_force_N']=(hardware[window,:3]/dt).mean(axis=0).tolist() if has_source else None
 (out/'summary.json').write_text(json.dumps(result,indent=2))
 os.environ.setdefault('MPLCONFIGDIR','/tmp/regrip-matplotlib');import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,ax=plt.subplots(3,1,figsize=(8,9),sharex=True);ax[0].plot(t,(q[:,2]-q[reference,2])*1000,label='Actual free object');ax[0].plot(t,(sq[:,2]-sq[reference,2])*1000,label='Actual support');ax[0].set_ylabel('Vertical shift mm');ax[0].legend();ax[1].plot(t,support_force,label='Support resultant');ax[1].plot(t,finger[:,:,:3].sum(axis=1)[:,2]/dt,label='Finger force Z');ax[1].axhline(mass*9.81,color='k',ls='--',label='Weight');ax[1].set_ylabel('N');ax[1].legend();ax[2].plot(t,gap*1000);ax[2].set(xlabel='Actual end clock s',ylabel='Support gap mm');fig.suptitle(a.case+' — actual native SOFA;'+result['status']);fig.tight_layout();fig.savefig(out/'holding.png');plt.close(fig);print(json.dumps(result))
if __name__=='__main__':main()
